// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// TelegramGuest Verify Telegram login widget data and mint a single-use guest ticket
	// (POST /api/auth/telegram-guest)
	TelegramGuest(ctx context.Context, request TelegramGuestRequestObject) (TelegramGuestResponseObject, error)
	// TelegramSignup Verify Telegram login widget data and mint an organizer signup ticket
	// (POST /api/auth/telegram-signup)
	TelegramSignup(ctx context.Context, request TelegramSignupRequestObject) (TelegramSignupResponseObject, error)
	// CreateBooking Guest creates a booking (atomic reserve)
	// (POST /api/bookings)
	CreateBooking(ctx context.Context, request CreateBookingRequestObject) (CreateBookingResponseObject, error)
	// CancelBookingByToken Guest cancels a booking via manageToken
	// (POST /api/bookings/cancel)
	CancelBookingByToken(ctx context.Context, request CancelBookingByTokenRequestObject) (CancelBookingByTokenResponseObject, error)
	// CancelBookingByOrganizer Organizer cancels a booking on one of their own services
	// (POST /api/bookings/cancel-by-organizer)
	CancelBookingByOrganizer(ctx context.Context, request CancelBookingByOrganizerRequestObject) (CancelBookingByOrganizerResponseObject, error)
	// LookupBookings Look up a guest's bookings with a single-use ticket
	// (POST /api/bookings/lookup)
	LookupBookings(ctx context.Context, request LookupBookingsRequestObject) (LookupBookingsResponseObject, error)
	// RunJob Upstash QStash webhook consumer
	// (POST /api/jobs/{queue})
	RunJob(ctx context.Context, request RunJobRequestObject) (RunJobResponseObject, error)
	// RegisterOrganizer Register a new organizer using an auth ticket
	// (POST /api/organizers)
	RegisterOrganizer(ctx context.Context, request RegisterOrganizerRequestObject) (RegisterOrganizerResponseObject, error)
	// GetMyProfile Get the organizer this request may view (demo when anonymous)
	// (GET /api/organizers/me)
	GetMyProfile(ctx context.Context, request GetMyProfileRequestObject) (GetMyProfileResponseObject, error)
	// UpdateMyProfile Update organizer profile
	// (PUT /api/organizers/me)
	UpdateMyProfile(ctx context.Context, request UpdateMyProfileRequestObject) (UpdateMyProfileResponseObject, error)
	// CreateAvatarUploadTarget Mint a signed upload URL for an avatar image
	// (POST /api/organizers/me/avatar)
	CreateAvatarUploadTarget(ctx context.Context, request CreateAvatarUploadTargetRequestObject) (CreateAvatarUploadTargetResponseObject, error)
	// UpdateMyLanguage Update organizer notification language
	// (PATCH /api/organizers/me/language)
	UpdateMyLanguage(ctx context.Context, request UpdateMyLanguageRequestObject) (UpdateMyLanguageResponseObject, error)
	// CreateServicePhotoUploadTarget Mint a signed upload URL for a service cover photo
	// (POST /api/organizers/me/service-photo)
	CreateServicePhotoUploadTarget(ctx context.Context, request CreateServicePhotoUploadTargetRequestObject) (CreateServicePhotoUploadTargetResponseObject, error)
	// ListServices List the services of the organizer this request may view
	// (GET /api/services)
	ListServices(ctx context.Context, request ListServicesRequestObject) (ListServicesResponseObject, error)
	// CreateService Create a service
	// (POST /api/services)
	CreateService(ctx context.Context, request CreateServiceRequestObject) (CreateServiceResponseObject, error)
	// DeleteService Delete a service; slots and bookings cascade
	// (DELETE /api/services/{id})
	DeleteService(ctx context.Context, request DeleteServiceRequestObject) (DeleteServiceResponseObject, error)
	// GetService Get one service owned by the organizer this request may view
	// (GET /api/services/{id})
	GetService(ctx context.Context, request GetServiceRequestObject) (GetServiceResponseObject, error)
	// UpdateService Update a service
	// (PUT /api/services/{id})
	UpdateService(ctx context.Context, request UpdateServiceRequestObject) (UpdateServiceResponseObject, error)
	// ListSlots List slots across every service of the organizer this request may view
	// (GET /api/slots)
	ListSlots(ctx context.Context, request ListSlotsRequestObject) (ListSlotsResponseObject, error)
	// CreateSlot Create a time slot under one of the organizer's services
	// (POST /api/slots)
	CreateSlot(ctx context.Context, request CreateSlotRequestObject) (CreateSlotResponseObject, error)
	// DeleteSlot Delete a time slot
	// (DELETE /api/slots/{id})
	DeleteSlot(ctx context.Context, request DeleteSlotRequestObject) (DeleteSlotResponseObject, error)
	// GetSlot Get one slot owned by the organizer this request may view
	// (GET /api/slots/{id})
	GetSlot(ctx context.Context, request GetSlotRequestObject) (GetSlotResponseObject, error)
	// UpdateSlot Update a time slot; bookedCount is never writable
	// (PUT /api/slots/{id})
	UpdateSlot(ctx context.Context, request UpdateSlotRequestObject) (UpdateSlotResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// TelegramGuest operation middleware
func (sh *strictHandler) TelegramGuest(w http.ResponseWriter, r *http.Request) {
	var request TelegramGuestRequestObject

	var body TelegramGuestJSONRequestBody
	if err := json.NewDecoder(r.Body).Decode(&body); err != nil {
		sh.options.RequestErrorHandlerFunc(w, r, fmt.Errorf("can't decode JSON body: %w", err))
		return
	}
	request.Body = &body

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.TelegramGuest(ctx, request.(TelegramGuestRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "TelegramGuest")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(TelegramGuestResponseObject); ok {
		if err := validResponse.VisitTelegramGuestResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

